<script setup lang="ts">
import PhotoFieldMobile from './PhotoFieldMobile.vue';
import PhotoGridMobile from './PhotoGridMobile.vue';
import { api } from '../platform';
import { ref, watch } from 'vue';
import ForumAudioMobile from './ForumAudioMobile.vue';
import ForumAudioFieldMobile from './ForumAudioFieldMobile.vue';
import { type Row, forumCategories, statusNames, formatTime } from '../../../shared/domain';
import { useForum } from '../../../shared/useForum';
const props = defineProps<{ user: Row | null }>();const emit = defineEmits<{ (event: 'join'): void }>();
const { managed,managedReplies,restrictions,blocks,selected,replies,tab,category,query,error,message,busy,creating,form,reply,replyAudio,replyPhotos,quoted,operation,note,moderator,visible,detail,create,post,respond,ask,perform } = useForum(() => props.user,api);
const audioUploading = ref(false), photosPending = ref(false);
watch(() => [creating.value, selected.value?.id, props.user?.id], () => { audioUploading.value = false;photosPending.value = false; });
function newTopic(source?: Row) { if (props.user?.status !== 'approved') emit('join');else create(source); }
function board(event: any) { form.value.category = forumCategories[Number(event.detail.value)]; }
</script>
<template><view><template v-if="!creating && !selected"><view class="title">聊乡音，话家常</view><view class="intro">每一层回应，让老乡之间多一点了解。</view></template><view v-if="error" class="error">{{ error }}</view><view v-if="message" class="notice-line">{{ message }}</view>
<view v-if="operation" class="form-page"><button class="text-button" :disabled="busy" @click="operation = null">← 返回</button><view class="form-title">{{ operation.title }}</view><view class="meta">{{ operation.row.title || operation.row.authorName || operation.row.name }}</view><view v-if="operation.action === 'delete'" class="safe-note">确认后正文将清空，楼层与必要处理记录保留。</view><view v-if="!['approved','block','unblock','lock'].includes(operation.action)" class="field"><text class="field-label">处理说明（至少2字）</text><textarea v-model="note" maxlength="300"/></view><button class="primary" :disabled="busy" @click="perform">确认操作</button></view>
<view v-else-if="creating" class="form-page"><button class="text-button" @click="creating = false">← 返回论坛</button><view class="form-title">{{ form.forwardedTopicId ? '转发并说说看法' : '发起一个话题' }}</view><view class="field"><text class="field-label">标题</text><input v-model="form.title" maxlength="80"/></view><view class="field"><text class="field-label">板块</text><picker :range="forumCategories" @change="board"><view class="picker-value">{{ form.category }} ▾</view></picker></view><view class="field"><text class="field-label">分享内容（附照片或语音时选填）</text><textarea v-model="form.content" maxlength="5000" class="topic-textarea"/></view><PhotoFieldMobile v-model="form.photos" :user-id="user?.id" :disabled="busy" @busy="photosPending = $event"/><ForumAudioFieldMobile v-model="form.audio" :user-id="user?.id" @busy="audioUploading = $event"/><view class="safe-note">主题和回复经审核后展示；转发保留原帖来源，原帖隐藏后不再展示原文。</view><button class="primary" :disabled="busy || audioUploading || photosPending" @click="post">提交审核</button></view>
<template v-else-if="selected"><button class="text-button" @click="selected = null">← 返回话题列表</button><view class="panel"><text class="tag">{{ selected.category }} · {{ statusNames[selected.status] }}</text><view class="card-title">{{ selected.title }}</view><view class="meta">楼主 · {{ selected.authorName }} · {{ formatTime(selected.createdAt) }}</view><view class="prose topic-body">{{ selected.content }}</view><PhotoGridMobile :photos="selected.photos || []"/><ForumAudioMobile v-if="selected.audio" :attachment="selected.audio"/><view v-if="selected.forwarded" class="quoted-post"><view v-if="selected.forwarded.unavailable">原帖已不可见</view><template v-else><text>转发自 {{ selected.forwarded.authorName }}</text><view>{{ selected.forwarded.title }}</view><view>{{ selected.forwarded.content }}</view><PhotoGridMobile :photos="selected.forwarded.photos || []"/><ForumAudioMobile v-if="selected.forwarded.audio" :attachment="selected.forwarded.audio"/><button class="text-button" @click="detail(selected.forwarded)">查看原帖 →</button></template></view><view class="button-row"><button v-if="selected.status === 'approved'" class="outline small" @click="newTopic(selected)">转发</button><button v-if="user?.status === 'approved' && selected.authorId !== user.id" class="text-button" @click="ask(selected,'block')">拉黑作者</button><button v-if="!selected.locked && (selected.authorId === user?.id || selected.canModerate)" class="text-button" @click="ask(selected,'lock')">关闭回复</button><button v-if="selected.authorId === user?.id || selected.canModerate" class="text-button" @click="ask(selected,'delete')">删除</button><template v-if="selected.canModerate"><button v-if="selected.status === 'approved'" class="text-button" @click="ask(selected,'hidden')">隐藏</button><button class="text-button" @click="ask(selected,'mute')">禁言作者</button><button class="text-button" @click="ask(selected,'kick')">移出版块</button></template></view></view><view class="section-title">老乡的回复</view><view v-if="!replies.length" class="empty">还没有回复，来聊几句吧。</view><view v-for="(row,index) in replies" :key="row.id" class="panel"><view class="row"><text>{{ row.authorName }}</text><text class="meta">{{ row.floor || index + 1 }} 楼 · {{ statusNames[row.status] }}</text></view><view v-if="row.quoted" class="quoted-post"><text v-if="row.quoted.unavailable">引用内容已不可见</text><template v-else>{{ row.quoted.floor }}楼 · {{ row.quoted.authorName }}<view>{{ row.quoted.content }}</view><PhotoGridMobile :photos="row.quoted.photos || []"/><ForumAudioMobile v-if="row.quoted.audio" :attachment="row.quoted.audio"/></template></view><view class="prose topic-body">{{ row.status === 'deleted' ? '此层回复已删除' : row.content }}</view><PhotoGridMobile :photos="row.photos || []"/><ForumAudioMobile v-if="row.audio && row.status !== 'deleted'" :attachment="row.audio"/><view class="button-row"><button v-if="row.status === 'approved' && !selected.locked" class="text-button" @click="quoted = row">引用回复</button><button v-if="row.status !== 'deleted' && (row.authorId === user?.id || row.canModerate)" class="text-button" @click="ask(row,'delete','replies')">删除</button><button v-if="row.canModerate && row.status === 'approved'" class="text-button" @click="ask(row,'hidden','replies')">隐藏</button><button v-if="user?.status === 'approved' && row.authorId !== user.id" class="text-button" @click="ask(row,'block')">拉黑</button><button v-if="row.canModerate" class="text-button" @click="ask(row,'mute')">禁言</button></view></view><view v-if="selected.status === 'approved' && !selected.locked" class="form-page"><view v-if="quoted" class="quoted-post">回复 {{ quoted.floor }}楼 · {{ quoted.authorName }}<text @click="quoted = null"> 取消引用 ×</text></view><view class="field"><text class="field-label">发表回复</text><textarea v-model="reply" maxlength="2000" placeholder="友善交流，认真回应"/></view><PhotoFieldMobile :key="selected.id + replies.length" v-model="replyPhotos" :user-id="user?.id" :disabled="busy" @busy="photosPending = $event"/><ForumAudioFieldMobile :key="selected.id" v-model="replyAudio" :user-id="user?.id" @busy="audioUploading = $event"/><button class="primary" :disabled="busy || audioUploading || photosPending" @click="user?.status === 'approved' ? respond() : emit('join')">提交回复</button></view><view v-else class="notice-line">话题暂不接受新回复</view></template>
<template v-else><button class="primary" @click="newTopic()">＋ 发起话题</button><view class="pill-row forum-tabs"><text :class="['pill',{ active: tab === 'public' }]" @click="tab = 'public'">全部话题</text><text v-if="user" :class="['pill',{ active: tab === 'mine' }]" @click="tab = 'mine'">我的发布</text><text v-if="moderator" :class="['pill',{ active: tab === 'manage' }]" @click="tab = 'manage'">版主管理</text><text v-if="moderator" :class="['pill',{ active: tab === 'restrictions' }]" @click="tab = 'restrictions'">板块限制</text><text v-if="user" :class="['pill',{ active: tab === 'blocks' }]" @click="tab = 'blocks'">黑名单</text></view>
<template v-if="['public','mine'].includes(tab)"><input v-model="query" class="search" placeholder="搜索话题、内容、老乡"/><view class="pill-row"><text v-for="item in ['全部',...forumCategories]" :key="item" :class="['pill',{ active: category === item }]" @click="category = item">{{ item }}</text></view><view v-if="!visible.length" class="empty">有故事，一起聊。<br/>发起第一个话题吧。</view><view v-for="row in visible" :key="row.id" class="panel" @click="row.status !== 'deleted' && detail(row)"><text class="tag">{{ row.category }}</text><view class="card-title">{{ row.title }}</view><view class="post-excerpt">{{ row.content || (row.photos?.length ? row.photos.length + ' 张照片 · 点击查看' : row.audio ? '语音话题 · 点击收听' : '') }}</view><view class="meta">{{ row.authorName }} · {{ formatTime(row.createdAt) }}</view><view class="row"><text class="meta">{{ row.replyCount }} 条回复</text><text class="tag">{{ row.locked ? '已关闭回复' : statusNames[row.status] }}</text></view></view></template>
<template v-if="tab === 'manage'"><view class="safe-note">版主只可管理被分配的板块。隐藏可恢复，删除清空正文。</view><template v-for="section in [{ title: '话题管理', rows: managed, kind: 'topics' },{ title: '回复管理', rows: managedReplies, kind: 'replies' }]" :key="section.kind"><view class="section-title">{{ section.title }}</view><view v-if="!section.rows.length" class="empty">暂无内容</view><view v-for="row in section.rows" :key="row.id" class="panel"><text class="tag">{{ row.category }} · {{ statusNames[row.status] }}</text><view class="card-title">{{ row.title || row.authorName + '的回复' }}</view><view class="prose topic-body">{{ row.content }}</view><PhotoGridMobile :photos="row.photos || []"/><ForumAudioMobile v-if="row.audio" :attachment="row.audio"/><view class="button-row"><button v-if="row.status === 'pending' || row.status === 'hidden'" class="primary small" @click="ask(row,'approved',section.kind)">{{ row.status === 'hidden' ? '恢复展示' : '审核通过' }}</button><button v-if="row.status === 'pending'" class="outline small" @click="ask(row,'rejected',section.kind)">退回</button><button v-if="row.status === 'approved'" class="outline small" @click="ask(row,'hidden',section.kind)">隐藏</button><button v-if="row.status !== 'deleted'" class="text-button" @click="ask(row,'delete',section.kind)">删除</button><button class="text-button" @click="ask(row,'mute')">禁言作者</button><button class="text-button" @click="ask(row,'kick')">移出版块</button></view></view></template></template>
<template v-if="tab === 'restrictions'"><view class="safe-note">移出后限制账号参与该板块；公开内容仍可由访客浏览。</view><view v-if="!restrictions.length" class="empty">暂无板块限制</view><view v-for="row in restrictions" :key="row.id" class="panel"><view class="card-title">{{ row.name }} · {{ row.board }}</view><view class="meta">{{ row.action === 'kick' ? '已移出' : '已禁言' }} · {{ row.reason }}</view><button class="outline small" @click="ask(row,'restore')">恢复参与</button></view></template>
<template v-if="tab === 'blocks'"><view class="safe-note">拉黑后隐藏对方论坛内容，禁止新的私聊与联系方式交换请求。</view><view v-if="!blocks.length" class="empty">黑名单为空</view><view v-for="row in blocks" :key="row.id" class="panel row"><text>{{ row.name }}</text><button class="outline small" @click="ask(row,'unblock')">取消拉黑</button></view></template></template></view></template>
<style scoped>.forum-tabs{margin-top:30rpx}.topic-textarea{height:400rpx}.topic-body{white-space:pre-wrap;margin:25rpx 0;word-break:break-word}.quoted-post{background:#eee7d7;border-left:5rpx solid #c4a467;padding:24rpx;border-radius:12rpx;font-size:24rpx;line-height:1.9;color:#887a60;white-space:pre-wrap;margin:22rpx 0;word-break:break-word}.quoted-post>view{margin-top:12rpx}.panel .card-title{margin-top:20rpx}</style>
